import {
	createAssistantMessageEventStream,
	type Api,
	type AssistantMessage,
	type AssistantMessageEvent,
	type AssistantMessageEventStream,
	type Context,
	type Model,
	type SimpleStreamOptions,
} from "@earendil-works/pi-ai";
import {
	classifyLlmError,
	DEFAULT_API_RETRY_POLICY,
	isRetryableApiError,
	retryDelayMs,
	type ApiRetryPolicy,
} from "../core/api-retry.js";

export {
	classifyLlmError,
	isRetryableApiError,
	retryAfterDelayMs,
	retryDelayMs,
	retryableStatusCode,
	type ApiRetryPolicy,
	type LlmErrorCategory,
	type LlmErrorDetails,
} from "../core/api-retry.js";

export const WEB_API_RETRY_POLICY: ApiRetryPolicy = DEFAULT_API_RETRY_POLICY;

let nextStartAt = 0;

function errorText(error: unknown): string {
	if (error instanceof Error) return error.message;
	if (typeof error === "string") return error;
	try {
		return JSON.stringify(error);
	} catch {
		return String(error);
	}
}

function defaultUsage(): AssistantMessage["usage"] {
	return {
		input: 0,
		output: 0,
		cacheRead: 0,
		cacheWrite: 0,
		totalTokens: 0,
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
	};
}

function errorMessage(model: Model<Api>, error: unknown): AssistantMessage {
	return {
		role: "assistant",
		content: [],
		api: model.api,
		provider: model.provider,
		model: model.id,
		usage: defaultUsage(),
		stopReason: "error",
		errorMessage: errorText(error),
		timestamp: Date.now(),
	};
}

async function sleep(ms: number, signal?: AbortSignal): Promise<void> {
	if (ms <= 0) return;
	if (signal?.aborted) throw new Error("Request aborted");
	await new Promise<void>((resolve, reject) => {
		let timeout: ReturnType<typeof globalThis.setTimeout>;
		const cleanup = () => {
			globalThis.clearTimeout(timeout);
			signal?.removeEventListener("abort", abort);
		};
		const done = () => {
			cleanup();
			resolve();
		};
		const abort = () => {
			cleanup();
			reject(new Error("Request aborted"));
		};
		timeout = globalThis.setTimeout(done, ms);
		signal?.addEventListener("abort", abort, { once: true });
	});
}

async function waitForApiTurn(policy: ApiRetryPolicy, signal?: AbortSignal): Promise<void> {
	const now = Date.now();
	const waitMs = Math.max(0, nextStartAt - now);
	nextStartAt = Math.max(now, nextStartAt) + policy.rateLimitIntervalMs;
	await sleep(waitMs, signal);
}

export async function withApiRetry<T>(
	operation: () => Promise<T> | T,
	options: { policy?: ApiRetryPolicy; signal?: AbortSignal } = {},
): Promise<T> {
	const policy = options.policy ?? WEB_API_RETRY_POLICY;
	let lastError: unknown;

	for (let attempt = 0; attempt < policy.maxAttempts; attempt += 1) {
		await waitForApiTurn(policy, options.signal);
		try {
			return await operation();
		} catch (error) {
			lastError = error;
			if (attempt >= policy.maxAttempts - 1 || !isRetryableApiError(error)) throw error;
			await sleep(retryDelayMs(attempt, error, policy), options.signal);
		}
	}

	throw lastError;
}

function terminalErrorEvent(model: Model<Api>, error: unknown): AssistantMessageEvent {
	const message = errorMessage(model, error);
	return { type: "error", reason: "error", error: message };
}

function forwardBuffered(target: AssistantMessageEventStream, pending: AssistantMessageEvent[]): void {
	for (const event of pending) target.push(event);
	pending.length = 0;
}

function commitsAttempt(event: AssistantMessageEvent): boolean {
	if (event.type === "text_delta" || event.type === "thinking_delta") return event.delta.length > 0;
	return event.type === "toolcall_end" || event.type === "done";
}

type RetryAnnotatedMessage = AssistantMessage & {
	__keatingRetryAttempts?: number;
	__keatingRetryExhausted?: boolean;
};

function annotateRetryOutcome(
	message: AssistantMessage,
	attempts: number,
	exhausted: boolean,
): AssistantMessage {
	const annotated = message as RetryAnnotatedMessage;
	annotated.__keatingRetryAttempts = attempts;
	annotated.__keatingRetryExhausted = exhausted;
	return annotated;
}

export function streamWithApiRetry(
	model: Model<Api>,
	context: Context,
	options: SimpleStreamOptions | undefined,
	createStream: (options?: SimpleStreamOptions) => AssistantMessageEventStream,
	policy: ApiRetryPolicy = WEB_API_RETRY_POLICY,
): AssistantMessageEventStream {
	const target = createAssistantMessageEventStream();

	(async () => {
		let finalError: unknown;
		for (let attempt = 0; attempt < policy.maxAttempts; attempt += 1) {
			const pending: AssistantMessageEvent[] = [];
			let forwarded = false;
			let attemptError: AssistantMessage | null = null;

			try {
				await waitForApiTurn(policy, options?.signal);
				const source = createStream({
					...options,
					maxRetries: options?.maxRetries ?? 0,
					maxRetryDelayMs: options?.maxRetryDelayMs ?? policy.maxDelayMs,
				});

				for await (const event of source) {
					if (event.type === "error") {
						attemptError = event.error;
						break;
					}

					if (!forwarded) {
						pending.push(event);
						if (!commitsAttempt(event)) continue;
						forwardBuffered(target, pending);
						forwarded = true;
						continue;
					}
					target.push(event);
				}
			} catch (error) {
				attemptError = errorMessage(model, error);
			}

			if (!attemptError) return;
			finalError = attemptError.errorMessage ?? "API request failed";

			const details = classifyLlmError(finalError);
			const canRetry = !forwarded
				&& !options?.signal?.aborted
				&& attempt < policy.maxAttempts - 1
				&& details.automaticRetry;

			if (canRetry) {
				await sleep(retryDelayMs(attempt, finalError, policy), options?.signal);
				continue;
			}

			forwardBuffered(target, pending);
			const exhausted = details.automaticRetry && attempt >= policy.maxAttempts - 1;
			target.push({
				type: "error",
				reason: attemptError.stopReason === "aborted" ? "aborted" : "error",
				error: annotateRetryOutcome(attemptError, attempt + 1, exhausted),
			});
			return;
		}

		target.push(terminalErrorEvent(model, finalError ?? "API request failed"));
	})().catch((error) => {
		target.push(terminalErrorEvent(model, error));
	});

	return target;
}
export interface ApiRetryPolicy {
  maxAttempts: number;
  initialDelayMs: number;
  maxDelayMs: number;
  rateLimitIntervalMs: number;
  jitterRatio: number;
}

export const DEFAULT_API_RETRY_POLICY: ApiRetryPolicy = {
  maxAttempts: 4,
  initialDelayMs: 750,
  maxDelayMs: 30_000,
  rateLimitIntervalMs: 500,
  jitterRatio: 0.2
};

const RETRYABLE_STATUS_CODES = new Set([408, 409, 425, 429, 500, 502, 503, 504]);
const NON_RETRYABLE_STATUS_CODES = new Set([400, 401, 403, 404, 422]);

let nextStartAt = 0;

function clampNumber(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function sanitizeApiRetryPolicy(value: unknown): ApiRetryPolicy {
  const entry = value && typeof value === "object" ? value as Record<string, unknown> : {};
  const fromNumber = (key: keyof ApiRetryPolicy, fallback: number, min: number, max: number) => {
    const raw = entry[key];
    return typeof raw === "number" && Number.isFinite(raw)
      ? clampNumber(raw, min, max)
      : fallback;
  };

  return {
    maxAttempts: Math.round(fromNumber("maxAttempts", DEFAULT_API_RETRY_POLICY.maxAttempts, 1, 8)),
    initialDelayMs: Math.round(fromNumber("initialDelayMs", DEFAULT_API_RETRY_POLICY.initialDelayMs, 0, 60_000)),
    maxDelayMs: Math.round(fromNumber("maxDelayMs", DEFAULT_API_RETRY_POLICY.maxDelayMs, 0, 300_000)),
    rateLimitIntervalMs: Math.round(fromNumber("rateLimitIntervalMs", DEFAULT_API_RETRY_POLICY.rateLimitIntervalMs, 0, 60_000)),
    jitterRatio: fromNumber("jitterRatio", DEFAULT_API_RETRY_POLICY.jitterRatio, 0, 1)
  };
}

function errorText(error: unknown): string {
  if (error instanceof Error) return error.message;
  if (typeof error === "string") return error;
  try {
    return JSON.stringify(error);
  } catch {
    return String(error);
  }
}

export function retryableStatusCode(message: string): number | null {
  const matches = message.match(/\b(?:status|http|code|exit)?\s*[:=]?\s*(\d{3})\b/gi) ?? [];
  for (const match of matches) {
    const code = Number(match.match(/\d{3}/)?.[0]);
    if (RETRYABLE_STATUS_CODES.has(code) || NON_RETRYABLE_STATUS_CODES.has(code)) return code;
  }
  return null;
}

export function isRetryableApiError(error: unknown): boolean {
  const message = errorText(error);
  const normalized = message.toLowerCase();
  const status = retryableStatusCode(message);
  if (status !== null) return RETRYABLE_STATUS_CODES.has(status);

  if (/\b(api[_ -]?key|unauthorized|authentication|permission denied|forbidden|invalid argument|bad request)\b/i.test(message)) {
    return false;
  }

  return /\b(rate limit|rate_limit|too many requests|resource_exhausted|quota|throttl|overload|unavailable|timeout|timed out|econnreset|econnrefused|socket hang up|network error|temporarily unavailable|try again later)\b/i.test(normalized);
}

export function retryAfterDelayMs(error: unknown): number | null {
  const message = errorText(error);
  const retryAfter = message.match(/retry-after\s*[:=]\s*([^\n,;]+)/i);
  if (!retryAfter) return null;

  const value = retryAfter[1].trim();
  const seconds = Number(value);
  if (Number.isFinite(seconds)) return Math.max(0, seconds * 1000);

  const dateMs = Date.parse(value);
  if (Number.isFinite(dateMs)) return Math.max(0, dateMs - Date.now());
  return null;
}

export function retryDelayMs(attemptIndex: number, error: unknown, policy: ApiRetryPolicy): number {
  const retryAfter = retryAfterDelayMs(error);
  const exponential = policy.initialDelayMs * 2 ** attemptIndex;
  const base = retryAfter ?? exponential;
  const capped = policy.maxDelayMs === 0 ? base : Math.min(base, policy.maxDelayMs);
  const jitter = capped * policy.jitterRatio * Math.random();
  return Math.round(capped + jitter);
}

async function sleep(ms: number): Promise<void> {
  if (ms <= 0) return;
  await new Promise((resolve) => setTimeout(resolve, ms));
}

export async function waitForApiTurn(policy: ApiRetryPolicy): Promise<void> {
  const now = Date.now();
  const waitMs = Math.max(0, nextStartAt - now);
  nextStartAt = Math.max(now, nextStartAt) + policy.rateLimitIntervalMs;
  await sleep(waitMs);
}

export async function withApiRetry<T>(
  operation: () => Promise<T> | T,
  policy: ApiRetryPolicy = DEFAULT_API_RETRY_POLICY,
): Promise<T> {
  const attempts = Math.max(1, Math.round(policy.maxAttempts));
  let lastError: unknown;

  for (let attempt = 0; attempt < attempts; attempt += 1) {
    await waitForApiTurn(policy);
    try {
      return await operation();
    } catch (error) {
      lastError = error;
      if (attempt >= attempts - 1 || !isRetryableApiError(error)) throw error;
      await sleep(retryDelayMs(attempt, error, policy));
    }
  }

  throw lastError;
}

